(28425, 'Summon Type A Periodic (3 sec)', 'Invocation de type A périodique (3 sec.)', 'Beschwörung Typ A, regelmäßig (3 Sek.)', 'Summon Type A Periodic (3 sec)', '週期性的召喚A型態 (3秒)', 'Invocar tipo A periódico (3 s)', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
(28426, 'Summon Type B Periodic (30 sec)', 'Invocation de type B périodique (30 sec.)', 'Beschwörung Typ B, regelmäßig (30 Sek.)', 'Summon Type B Periodic (30 sec)', '週期性的召喚B型態 (30秒)', 'Invocar tipo B periódico (30 s)', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', '', ''),
