INSERT INTO "world"."mail_text_template" ("entry", "content_default", "content_loc1", "content_loc2", "content_loc3", "content_loc4", "content_loc5", "content_loc6", "content_loc7") VALUES
(83, 'this is a test', '시험용 편지입니다.', 'Ceci est un test', 'this is a test', 'this is a test', 'this is a test', 'esto es una prueba', ''),
(84, 'Thank you for visiting me, $N. It makes me happy to know we are not forgotten.', '나를 방문해 주어서 고맙군, $N. 우리가 잊혀지지 않았다는 사실을 알게 되어 행복하다네.', 'Merci de m’avoir rendu visite, $N. Il est bon de savoir que nous ne sommes pas oubliés.', 'Danke für Euren Besuch, $N. Es macht mich glücklich zu wissen, dass man uns nicht vergessen hat.', '感谢你来看望我，$n。我很高兴，因为我们还没有被遗忘。', '謝謝你來看我，$N。我很高興知道我們沒被遺忘。', 'Gracias por visitarme, $N. Me complace saber que no se nos ha olvidado.', ''),
(85, 'Thank you for visiting me, $N. It makes me happy to know we are not forgotten.', '나를 방문해 주어서 고맙군, $N. 우리가 잊혀지지 않았다는 사실을 알게 되어 행복하다네.', 'Merci de m’avoir rendu visite, $N. Il est bon de savoir que nous ne sommes pas oubliés.', 'Danke für Euren Besuch, $N. Es macht mich glücklich zu wissen, dass man uns nicht vergessen hat.', '感谢你来看望我，$n。我很高兴，因为我们还没有被遗忘。', '謝謝你來看我，$N。我很高興知道我們沒被遺忘。', 'Gracias por visitarme, $N. Me complace saber que no se nos ha olvidado.', ''),
(86, 'This small token will give no answers, but perhaps it will be of some amusement to you.', '이 징표가 자네에게 해답을 주진 않겠지만 자네에게 작은 즐거움이 될 걸세.', 'Cette babiole ne vous apportera aucune réponse, mais elle vous amusera peut-être.', 'Dieses Kleinod wird Euch zwar keine Antworten geben, aber vielleicht findet Ihr ja Gefallen daran.', '这件小小的礼物不会给你答案，但也许它可以让你感到快乐。', '這個小東西雖然不會說話，但是或許能為你帶來一些歡樂。', 'Este pequeño objeto no te dará respuestas, pero puede resultarte divertido.', ''),
(87, 'Hello there again.  I''m Gubber Blump.
INSERT INTO "world"."mangos_string" ("entry", "content_default", "content_loc1", "content_loc2", "content_loc3", "content_loc4", "content_loc5", "content_loc6", "content_loc7", "content_loc8") VALUES
(1, 'You should select a character or a creature.', '캐릭터나 생물을 선택해야 합니다.', 'Vous devez sélectionner un personnage ou une créature.', 'Sie sollten einen Charakter oder eine Kreatur auswählen.', '您应该选择一个角色或一个生物。', NULL, 'Debes seleccionar un personaje o una criatura.', NULL, 'Вы должны выбрать персонажа или существо.'),
(2, 'You should select a creature.', '생물을 선택해야 합니다.', 'Vous devez sélectionner une créature.', 'Sie sollten eine Kreatur auswählen.', '你应该选择一个生物。', NULL, 'Debes seleccionar una criatura.', NULL, 'Вы должны выбрать существо.'),
(3, '|cffff0000[System Message]: %s|r', '|cffff0000[시스템 메시지]: %s|r', '|cffff0000[Message Système]:|r %s', '|cffff0000[Systemmeldung]: %s|r', '|cffff0000[系统消息]：%s|r', NULL, '|cffff0000[Mensaje del sistema]: %s|r', NULL, '|cffff0000[Системное сообщение]: %s|r'),
(4, '|cffff0000[Event Message]: %s|r', '|cffff0000[이벤트 메시지]: %s|r', '|cffff0000[Annonce d''événement]:|r %s', '|cffff0000[Ereignismeldung]: %s|r', '|cffff0000[事件消息]：%s|r', NULL, '|cffff0000[Mensaje de evento]: %s|r', NULL, '|cffff0000[Сообщение о событии]: %s|r'),
(5, 'There is no help for that command', '해당 명령에 대한 도움말이 없습니다.', 'Aucune aide n''est disponible pour cette commande.', 'Für diesen Befehl gibt es keine Hilfe', '该命令没有帮助', NULL, 'No hay ayuda para ese comando.', NULL, 'Нет помощи для этой команды'),
(6, 'There is no such command', '그런 명령이 없습니다', 'Cette commande n''existe pas.', 'Es gibt keinen solchen Befehl', '没有这样的命令', NULL, 'No hay tal comando', NULL, 'Нет такой команды'),
(7, 'There is no such subcommand', '해당 하위 명령이 없습니다.', 'Cette sous-commande n''existe pas.', 'Es gibt keinen solchen Unterbefehl', '没有这样的子命令', NULL, 'No hay tal subcomando', NULL, 'Нет такой подкоманды'),
(8, 'Command %s have subcommands:', '%s 명령에는 하위 명령이 있습니다.', 'La commande %s a des sous-commandes :', 'Befehl %s hat Unterbefehle:', '命令 %s 有子命令：', NULL, 'El comando %s tiene subcomandos:', NULL, 'Команда %s имеет подкоманды:'),
(9, 'Commands available to you:', '사용 가능한 명령:', 'Commandes disponibles:', 'Ihnen zur Verfügung stehende Befehle:', '您可以使用的命令：', NULL, 'Comandos disponibles para usted:', NULL, 'Доступные вам команды:'),
(10, 'Incorrect syntax.', '잘못된 구문입니다.', 'Syntaxe incorrecte.', 'Falsche Syntax.', '语法不正确。', NULL, 'Sintaxis incorrecta.', NULL, 'Неправильный синтаксис.'),
(11, 'Your account level is: %i', '귀하의 계정 레벨: %i', 'Votre niveau de compte est: %i', 'Ihr Kontolevel ist: %i', '您的帐户级别是：%i', NULL, 'El nivel de su cuenta es: %i', NULL, 'Уровень вашей учетной записи: %i'),
(12, 'Online players: %u (max: %u) Queued players: %u (max: %u)', '온라인 플레이어: %u(최대: %u) 대기열에 있는 플레이어: %u(최대: %u)', 'Joueurs en ligne: %u (max: %u) Joueurs dans la file d''attente: %u (max: %u)', 'Online-Spieler: %u (max: %u) Spieler in der Warteschlange: %u (max: %u)', '在线玩家：%u（最大值：%u）排队玩家：%u（最大值：%u）', NULL, 'Jugadores en línea: %u (máx.: %u) Jugadores en cola: %u (máx.: %u)', NULL, 'Игроки онлайн: %u (максимум: %u) Игроки в очереди: %u (максимум: %u)'),
(13, 'Server uptime: %s', '서버 가동 시간: %s', 'Serveur en-ligne depuis: %s', 'Server-Betriebszeit: %s', '服务器正常运行时间：%s', NULL, 'Tiempo de actividad del servidor: %s', NULL, 'Время работы сервера: %s'),
(14, 'Player saved.', '플레이어가 저장되었습니다.', 'Joueur sauvegardé.', 'Spieler gespeichert.', '玩家已保存。', NULL, 'Jugador salvado.', NULL, 'Игрок сохранен.'),
(15, 'All players saved.', '모든 플레이어가 저장되었습니다.', 'Tous les joueurs ont été sauvegardés.', 'Alle Spieler gespeichert.', '所有玩家都得救了。', NULL, 'Todos los jugadores salvados.', NULL, 'Все игроки сохранены.'),
(16, 'There are the following active GMs on this server:', '이 서버에는 다음과 같은 활성 GM이 있습니다.', 'Maîtres-du-jeu disponibles:', 'Es gibt die folgenden aktiven GMs auf diesem Server:', '此服务器上有以下活动 GM：', NULL, 'Hay los siguientes GM activos en este servidor:', NULL, 'На этом сервере есть следующие активные ГМ:'),
(17, 'There are no GMs currently logged in on this server.', '현재 이 서버에 로그인한 GM이 없습니다.', 'Aucun Maître-du-jeu n''est actuellement connecté.', 'Derzeit sind keine GMs auf diesem Server angemeldet.', '当前没有 GM 登录此服务器。', NULL, 'Actualmente no hay GM conectados en este servidor.', NULL, 'В настоящее время на этом сервере нет зарегистрированных GM.'),
(18, 'Cannot do that while flying.', '비행 중에는 할 수 없습니다.', 'Vous ne pouvez pas faire cela en vol.', 'Beim Fliegen geht das nicht.', '飞行时不能这样做。', NULL, 'No se puede hacer eso mientras se vuela.', NULL, 'Во время полета этого сделать нельзя.'),
(19, 'Cannot do that in Battlegrounds.', '전장에서는 그렇게 할 수 없습니다.', 'Vous ne pouvez pas faire cela sur un champ de Bataille.', 'In Schlachtfeldern geht das nicht.', '在战场上不能那样做。', NULL, 'No se puede hacer eso en Battlegrounds.', NULL, 'Невозможно сделать это на полях сражений.'),
(20, 'Target is flying you can''t do that.', '목표물이 날고 있습니다. 그렇게 할 수 없습니다.', 'La cible est en vol, vous ne pouvez pas faire cela.', 'Ziel fliegt, das geht nicht.', '目标在飞，你不能那样做。', NULL, 'El objetivo está volando, no puedes hacer eso.', NULL, 'Цель летит, вы не можете этого сделать.'),
(21, '%s is flying command failed.', '%s is flying 명령이 실패했습니다.', '%s est en vol, la commande a échoué.', '%s ist Flugbefehl fehlgeschlagen.', '%s 飞行命令失败。', NULL, '%s es un comando de vuelo fallido.', NULL, '%s - команда полета не удалась.'),
(22, 'You are not mounted so you can''t dismount.', '마운트되지 않았으므로 마운트 해제할 수 없습니다.', 'Vous n''êtes pas sur une monture, vous ne pouvez donc pas en descendre.', 'Du bist nicht beritten, also kannst du nicht absteigen.', '你没有上马，所以你不能下马。', NULL, 'No estás montado, así que no puedes desmontar.', NULL, 'Вы не в седле, поэтому не можете спешиться.'),
(23, 'Cannot do that while fighting.', '싸우는 동안에는 그렇게 할 수 없습니다.', 'Vous ne pouvez pas faire cela en combattant.', 'Im Kampf geht das nicht.', '战斗时不能那样做。', NULL, 'No se puede hacer eso mientras se lucha.', NULL, 'Во время боя этого делать нельзя.'),
(24, 'You used it recently.', '최근에 사용하셨습니다.', 'Vous l''avez déjà utilisé récemment.', 'Sie haben es kürzlich verwendet.', '你最近用过它。', NULL, 'Lo usaste recientemente.', NULL, 'Вы использовали его недавно.'),
(25, 'Password not changed (unknown error)!', '암호가 변경되지 않았습니다(알 수 없는 오류)!', 'Le mot de passe n''a pas été changé (erreur inconnue) !', 'Passwort nicht geändert (unbekannter Fehler)!', '密码未更改（未知错误）！', NULL, '¡Contraseña no cambiada (error desconocido)!', NULL, 'Пароль не изменен (неизвестная ошибка)!'),
(26, 'The password was changed', '비밀번호가 변경되었습니다', 'Le mot de passe a été changé.', 'Das Passwort wurde geändert', '密码已更改', NULL, 'La contraseña fue cambiada', NULL, 'Пароль был изменен'),
(27, 'The old password is wrong', '이전 암호가 잘못되었습니다.', 'L''ancien mot de passe est erroné', 'Das alte Passwort ist falsch', '旧密码错误', NULL, 'La contraseña anterior es incorrecta', NULL, 'Старый пароль неверный'),
(28, 'Your account is now locked.', '이제 귀하의 계정이 잠겼습니다.', 'Votre compte est maintenant bloqué.', 'Ihr Konto ist jetzt gesperrt.', '您的帐户现已被锁定。', NULL, 'Su cuenta ahora está bloqueada.', NULL, 'Теперь ваша учетная запись заблокирована.'),
(29, 'Your account is now unlocked.', '이제 귀하의 계정이 잠금 해제되었습니다.', 'Votre compte est maintenant débloqué.', 'Ihr Konto ist jetzt entsperrt.', '您的帐户现已解锁。', NULL, 'Su cuenta ahora está desbloqueada.', NULL, 'Теперь ваша учетная запись разблокирована.'),
(30, ', rank ', ', 순위 ', ', rang ', ', Rang ', ', 排名 ', NULL, ', rango ', NULL, ', классифицировать '),
(31, ' [known]', '[모두 다 아는]', '[connu]', '[bekannt]', '[已知]', NULL, '[conocido]', NULL, '[известен]'),
(32, ' [learn]', '[배우다]', '[appris]', '[lernen]', '[学习]', NULL, '[aprender]', NULL, '[учиться]'),
(33, ' [passive]', '[수동적인]', '[passive]', '[passiv]', '[被动的]', NULL, '[pasivo]', NULL, '[пассивный]'),
(34, ' [talent]', '[재능]', '[talent]', '[Talent]', '[天赋]', NULL, '[talento]', NULL, '[талант]'),
(35, ' [active]', '[활동적인]', '[actif]', '[aktiv]', '[积极的]', NULL, '[activo]', NULL, '[активный]'),
(36, ' [complete]', '[완벽한]', '[terminé]', '[vollständig]', '[完全的]', NULL, '[completo]', NULL, '[полный]'),
(37, ' (offline)', '(오프라인)', '(hors ligne)', '(offline)', '（离线）', NULL, '(desconectado)', NULL, '(не в сети)'),
(38, 'on', '~에', NULL, 'An', '在', NULL, 'en', NULL, 'на'),
(39, 'off', '끄다', NULL, 'aus', '离开', NULL, 'apagado', NULL, 'выключенный'),
(40, 'You are: %s', '당신은: %s', 'Vous êtes: %s', 'Sie sind: %s', '你是：%s', NULL, 'eres: %s', NULL, 'Вы: %s'),
(41, 'visible', '보이는', NULL, 'sichtbar', '可见的', NULL, NULL, NULL, 'видимый'),
(42, 'invisible', '보이지 않는', NULL, 'unsichtbar', '无形的', NULL, NULL, NULL, 'невидимый'),
(43, 'done', '완료', 'fait', 'Erledigt', '完毕', NULL, 'hecho', NULL, 'сделанный'),
(44, 'You', '너', 'Vous', 'Du', '你', NULL, 'Tú', NULL, 'Ты'),
(45, ' <unknown> ', '<알 수 없음> ', '<inconnu> ', '<unbekannt> ', '<未知> ', NULL, '<desconocido> ', NULL, '<неизвестно> '),
(46, '<error>', '<오류>', '<erreur>', '<Fehler>', '<错误>', NULL, NULL, NULL, '<ошибка>'),
(47, '<non-existing character>', '<존재하지 않는 캐릭터>', '<personnage inexistant>', '<nicht vorhandener Charakter>', '<不存在的角色>', NULL, '<personaje inexistente>', NULL, '<несуществующий персонаж>'),
(48, 'UNKNOWN', '알려지지 않은', 'INCONNU', 'UNBEKANNT', '未知', NULL, 'DESCONOCIDO', NULL, 'НЕИЗВЕСТНЫЙ'),
(49, 'You must be at least level %u to enter.', '입장하려면 레벨 %u 이상이어야 합니다.', 'Vous devez avoir le niveau %u pour entrer.', 'Sie müssen mindestens Level %u erreicht haben, um teilnehmen zu können.', '您必须至少达到 %u 级才能进入。', NULL, 'Debes tener al menos el nivel %u para participar.', NULL, 'Для входа вы должны быть не ниже %u уровня.'),
(371, 'INSTACAST cheat is OFF', 'INSTACAST 치트가 꺼져 있습니다.', 'La triche INSTACAST est désactivée', 'INSTACAST-Cheat ist AUS', 'INSTACAST作弊已关闭', NULL, 'El truco de INSTACAST está DESACTIVADO', NULL, 'Чит INSTACAST ВЫКЛЮЧЕН'),
(619, 'You set instant casting mode to %s for %s.', '%s에 대해 인스턴트 캐스팅 모드를 %s(으)로 설정했습니다.', 'Vous avez défini le mode de diffusion instantanée sur %s pour %s.', 'Sie haben den Instant-Casting-Modus für %s auf %s gesetzt.', '您将 %s 的即时施法模式设置为 %s。', NULL, 'Estableciste el modo de transmisión instantánea en %s para %s.', NULL, 'Вы установили режим мгновенного каста на %s для %s.'),
(51, 'Hello! Ready for some training?', '안녕하세요!', 'Bonjour ! Prêt pour l''entrainement ?', 'Hallo!', '你好！', NULL, '¡Hola!', NULL, 'Привет!'),
(52, 'Invaid item count (%u) for item %u', '항목 %u에 대한 잘못된 항목 수(%u)', 'Nombre d''objets invalide (%u) pour l''objet %u', 'Ungültige Artikelanzahl (%u) für Artikel %u', '项目 %u 的项目计数 (%u) 无效', NULL, 'Recuento de artículos no válidos (%u) para el artículo %u', NULL, 'Недопустимое количество элементов (%u) для элемента %u'),
(53, 'Mail can''t have more %u item stacks', '메일은 더 이상 %u 항목 스택을 가질 수 없습니다.', 'Le courrier ne peut pas contenir plus de %u objets', 'Post kann nicht mehr %u Artikelstapel haben', '邮件不能有更多 %u 个项目堆栈', NULL, 'El correo no puede tener más %u pilas de elementos', NULL, 'Почта не может иметь более %u стеков предметов'),
(54, 'The new passwords do not match', '새 비밀번호가 일치하지 않습니다', 'Les nouveaux mots de passe ne correspondent pas', 'Die neuen Passwörter stimmen nicht überein', '新密码不匹配', NULL, 'Las nuevas contraseñas no coinciden', NULL, 'Новые пароли не совпадают'),
(55, 'Your password can''t be longer than 16 characters (client limit), password not changed!', '비밀번호는 16자(클라이언트 제한)를 초과할 수 없으며 비밀번호는 변경되지 않습니다!', 'Votre mot de passe ne peut pas dépasser 16 caractères (limite du client). Mot de passe inchangé !', 'Ihr Passwort darf nicht länger als 16 Zeichen sein (Client-Limit), Passwort nicht geändert!', '您的密码不能超过 16 个字符（客户端限制），密码未更改！', NULL, 'Su contraseña no puede tener más de 16 caracteres (límite de clientes), ¡la contraseña no se cambia!', NULL, 'Ваш пароль не может быть длиннее 16 символов (ограничение клиента), пароль не менялся!'),
(56, 'Current Message of the day: 
INSERT INTO "world"."mangos_string" ("entry", "content_default", "content_loc1", "content_loc2", "content_loc3", "content_loc4", "content_loc5", "content_loc6", "content_loc7", "content_loc8") VALUES
(134, '%s has no more access to all taxi nodes now (only visited accessible).', '%s는 이제 모든 택시 노드에 더 이상 액세스할 수 없습니다(방문한 사람만 액세스 가능).', '%s n''a maintenant plus accès à tous les trajets aériens (seuls ceux visités lui sont accessibles).', '%s hat jetzt keinen Zugriff mehr auf alle Taxi-Knoten (nur besucht zugänglich).', '%s 现在无法访问所有出租车节点（仅可访问）。', NULL, '%s ya no tiene acceso a todos los nodos de taxi ahora (solo visitado accesible).', NULL, '%s больше не имеет доступа ко всем узлам такси (доступны только посещенные).'),
(135, '%s has given you access to all taxi nodes (until logout).', '%s님이 모든 택시 노드에 대한 액세스 권한을 부여했습니다(로그아웃할 때까지).', '%s vous a donné l''accès à tous les trajets aériens (jusqu''à votre déconnexion).', '%s hat Ihnen Zugriff auf alle Taxiknoten gewährt (bis zum Abmelden).', '%s 已授予您访问所有出租车节点的权限（直到注销）。', NULL, '%s le ha dado acceso a todos los nodos de taxi (hasta que cierre la sesión).', NULL, '%s предоставил вам доступ ко всем узлам такси (до выхода из системы).'),
(136, '%s has removed access to all taxi nodes (only visited still accessible).', '%s에서 모든 택시 노드에 대한 액세스 권한을 제거했습니다(방문한 항목만 계속 액세스 가능).', '%s vous a retiré l''accès à tous les trajets aériens (seuls ceux visités vous sont accessibles).', '%s hat den Zugriff auf alle Taxiknoten entfernt (nur besuchte noch zugänglich).', '%s 已经删除了对所有出租车节点的访问（只有访问过的仍然可以访问）。', NULL, '%s ha eliminado el acceso a todos los nodos de taxi (solo los visitados aún son accesibles).', NULL, '%s удалил доступ ко всем узлам такси (по-прежнему доступны только посещенные).'),
(137, 'You set all speeds to %2.2f from normal of %s.', NULL, 'Vous avez modifié toutes les vitesses à %2.2f par rapport à la normale pour le joueur %s.', NULL, NULL, NULL, 'Configuró todas las velocidades a %2.2f de lo normal de %s.', NULL, 'Вы установили все скорости на %2.2f от нормальной %s.'),
(138, '%s set all your speeds to %2.2f from normal.', '%s 모든 속도를 정상에서 %2.2f로 설정했습니다.', '%s a modifié toutes vos vitesses à %2.2f par rapport à la normale.', '%s hat alle deine Geschwindigkeiten von normal auf %2.2f gesetzt.', '%s 将你所有的速度从正常设置为 %2.2f。', NULL, '%s fijó todas sus velocidades a %2.2f de lo normal.', NULL, '%s установил все ваши скорости на %2.2f от нормальной.'),
(139, 'You set the speed to %2.2f from normal of %s.', NULL, 'Vous avez modifié la vitesse à %2.2f par rapport à la normale pour le joueur %s.', NULL, NULL, NULL, 'Configuró la velocidad a %2.2f desde la normal de %s.', NULL, 'Вы установили скорость %2.2f от нормальной %s.'),
(140, '%s set your speed to %2.2f from normal.', '%s 속도를 정상에서 %2.2f로 설정했습니다.', '%s a modifié votre vitesse à %2.2f par rapport à la normale.', '%s hat deine Geschwindigkeit von normal auf %2.2f gesetzt.', '%s 将你的速度从正常设置为 %2.2f。', NULL, '%s fijó su velocidad a %2.2f de lo normal.', NULL, '%s установил вашу скорость на %2.2f от нормальной.'),
(141, 'You set the swim speed to %2.2f from normal of %s.', NULL, 'Vous avez modifié la vitesse de nage à %2.2f par rapport à la normale pour le joueur %s.', NULL, NULL, NULL, 'Estableciste la velocidad de nado a %2.2f de la normal de %s.', NULL, 'Вы установили скорость плавания на %2.2f от нормальной %s.'),
(142, '%s set your swim speed to %2.2f from normal.', '%s 수영 속도를 정상에서 %2.2f로 설정했습니다.', '%s a modifié votre vitesse de nage à %2.2f par rapport à la normale.', '%s hat deine Schwimmgeschwindigkeit von normal auf %2.2f gesetzt.', '%s 将你的游泳速度从正常设置为 %2.2f。', NULL, '%s fijó su velocidad de nado a %2.2f de lo normal.', NULL, '%s установил скорость плавания на %2.2f от нормальной.'),
(143, 'You set the backwards run speed to %2.2f from normal of %s.', NULL, 'Vous avez modifié la vitesse de recul à %2.2f par rapport à la normale pour le joueur %s.', NULL, '您将向后运行速度设置为 %2.2f，从 %s 的正常值开始。', NULL, 'Configuró la velocidad de carrera hacia atrás a %2.2f desde lo normal de %s.', NULL, 'Вы установили скорость обратного хода на %2.2f по сравнению с нормальной %s.'),
(144, '%s set your backwards run speed to %2.2f from normal.', '%s 역주행 속도를 정상에서 %2.2f로 설정했습니다.', '%s a modifié votre vitesse recul à %2.2f par rapport à la normale.', '%s hat deine Rückwärtslaufgeschwindigkeit von normal auf %2.2f gesetzt.', '%s 将你的倒跑速度从正常设置为 %2.2f。', NULL, '%s estableció su velocidad de carrera hacia atrás a %2.2f de lo normal.', NULL, '%s установил скорость бега назад на %2.2f от нормальной.'),
(147, 'You set the size %2.2f of %s.', NULL, 'Vous avez modifié la taille à %2.2f par rapport à la normale pour le joueur %s.', 'Sie legen die Größe %2.2f von %s fest.', '您将 %2.2f 的大小设置为 %s。', NULL, 'Usted establece el tamaño %2.2f de %s.', NULL, 'Вы установили размер %2.2f из %s.'),
(148, '%s set your size to %2.2f.', '%s 크기를 %2.2f로 설정하십시오.', '%s a modifié votre taille à %2.2f par rapport à la normale.', '%s setze deine Größe auf %2.2f.', '%s 将您的尺寸设置为 %2.2f。', NULL, '%s establece tu tamaño en %2.2f.', NULL, '%s установите размер %2.2f.'),
(149, 'There is no such mount.', '그런 마운트가 없습니다.', 'Cette monture n''existe pas.', 'Es gibt keine solche Halterung.', '没有这样的坐骑。', NULL, 'No existe ese montaje.', NULL, 'Нет такого крепления.'),
(150, 'You give a mount to %s.', '%s에 마운트를 제공합니다.', 'Vous donnez une monture à %s.', 'Du gibst %s ein Reittier.', '你给 %s 一个坐骑。', NULL, 'Le das una montura a %s.', NULL, 'Вы даете средство передвижения %s.'),
(151, '%s gave you a mount.', '%s님이 탈것을 주셨습니다.', '%s vous a donné une monture.', '%s hat dir ein Reittier gegeben.', '%s 给了你一个坐骑。', NULL, '%s te dio una montura.', NULL, '%s дал вам средство передвижения.'),
(152, 'USER1: %i, ADD: %i, DIF: %i
INSERT INTO "world"."mangos_string" ("entry", "content_default", "content_loc1", "content_loc2", "content_loc3", "content_loc4", "content_loc5", "content_loc6", "content_loc7", "content_loc8") VALUES
(263, 'Target map or coordinates is invalid (X: %f Y: %f MapId: %u)', '대상 지도 또는 좌표가 잘못되었습니다(X: %f Y: %f MapId: %u).', 'Carte ou coordonnées de destination invalides (X: %f Y: %f MapId: %u).', 'Zielkarte oder Koordinaten sind ungültig (X: %f Y: %f MapId: %u)', '目标地图或坐标无效（X：%f Y：%f MapId：%u）', NULL, 'El mapa de destino o las coordenadas no son válidos (X: %f Y: %f MapId: %u)', NULL, 'Недопустимая карта или координаты цели (X: %f Y: %f MapId: %u)'),
(264, 'Zone coordinates is invalid (X: %f Y: %f AreaId: %u)', '구역 좌표가 잘못되었습니다(X: %f Y: %f AreaId: %u).', 'Coordonnées de zone invalides (X: %f Y: %f AreaId: %u)', 'Zonenkoordinaten sind ungültig (X: %f Y: %f AreaId: %u)', '区域坐标无效（X：%f Y：%f AreaId：%u）', NULL, 'Las coordenadas de zona no son válidas (X: %f Y: %f AreaId: %u)', NULL, 'Координаты зоны недействительны (X: %f Y: %f AreaId: %u)'),
(265, 'Zone %u (%s) is part of instanceable map %u (%s)', '영역 %u(%s)는 인스턴스 가능한 맵 %u(%s)의 일부입니다.', 'La zone %u (%s) est une partie de l''instance %u (%s)', 'Zone %u (%s) ist Teil der instanzierbaren Karte %u (%s)', '区域 %u (%s) 是可实例化映射 %u (%s) 的一部分', NULL, 'La zona %u (%s) es parte del mapa instanciable %u (%s)', NULL, 'Зона %u (%s) является частью инстансируемой карты %u (%s)'),
(266, 'Nothing found!', '아무것도 찾을 수 없음!', 'Rien n''a été trouvé !', 'Nichts gefunden!', '什么都没找到！', NULL, '¡Nada Encontrado!', NULL, 'Ничего не найдено!'),
(267, 'Object not found!', '개체를 찾을 수 없습니다!', 'Objet introuvable !', 'Objekt nicht gefunden!', '找不到对象！', NULL, '¡Objeto no encontrado!', NULL, 'Объект не найден!'),
(268, 'Creature not found!', '생물을 찾을 수 없습니다!', 'Créature introuvable !', 'Kreatur nicht gefunden!', '找不到生物！', NULL, '¡Criatura no encontrada!', NULL, 'Существо не найдено!'),
(270, 'Creature Removed', '제거된 생물', 'Créature supprimée.', 'Kreatur entfernt', '生物移除', NULL, 'Criatura eliminada', NULL, 'Существо удалено'),
(271, 'Creature moved.', '생물이 움직였습니다.', 'Créature déplacée.', 'Kreatur bewegt.', '生物移动了。', NULL, 'La criatura se movió.', NULL, 'Существо двинулось.'),
(272, 'Creature (GUID:%u) must be on the same map as player!', '생물(GUID:%u)은 플레이어와 같은 맵에 있어야 합니다!', 'La créature (GUID: %u) doit être sur la même carte que le joueur !', 'Die Kreatur (GUID: %u) muss sich auf derselben Karte wie der Spieler befinden!', '生物 (GUID:%u) 必须与玩家在同一张地图上！', NULL, '¡La criatura (GUID:%u) debe estar en el mismo mapa que el jugador!', NULL, 'Существо (GUID:%u) должно находиться на той же карте, что и игрок!'),
(273, 'Game Object (GUID: %u) not found', '게임 개체(GUID: %u)를 찾을 수 없습니다.', 'Game Object (GUID: %u) introuvable.', 'Spielobjekt (GUID: %u) nicht gefunden', '未找到游戏对象（GUID：%u）', NULL, 'Objeto de juego (GUID: %u) no encontrado', NULL, 'Игровой объект (GUID: %u) не найден'),
(274, 'Game Object (GUID: %u) has references in not found owner %s GO list, can''t be deleted.', '게임 개체(GUID: %u)에는 찾을 수 없는 소유자 %s GO 목록에 참조가 있으므로 삭제할 수 없습니다.', 'L''objet de jeu (GUID : %u) a des références dans la liste GO du propriétaire introuvable %s, ne peut pas être supprimé.', 'Das Spielobjekt (GUID: %u) hat Referenzen in der GO-Liste des nicht gefundenen Besitzers %s, kann nicht gelöscht werden.', '游戏对象（GUID：%u）在未找到所有者 %s GO 列表中有引用，无法删除。', NULL, 'Game Object (GUID: %u) tiene referencias en la lista GO del propietario %s no encontrado, no se puede eliminar.', NULL, 'Игровой объект (GUID: %u) имеет ссылки в не найденном владельце %s GO list, не может быть удален.'),
(275, 'Game Object (GUID: %u) removed', '게임 개체(GUID: %u)가 제거됨', 'Game Object (GUID: %u) supprimé.', 'Spielobjekt (GUID: %u) entfernt', '移除游戏对象（GUID：%u）', NULL, 'Objeto de juego (GUID: %u) eliminado', NULL, 'Игровой объект (GUID: %u) удален'),
(276, 'Game Object |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) turned', '게임 오브젝트 |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) 회전', 'Game Object |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) tourné.', 'Spielobjekt |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) drehte sich', '游戏对象 |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u)', NULL, 'Objeto de juego |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) convertido', NULL, 'Игровой объект |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) повернулся'),
(277, 'Game Object |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) moved', '게임 오브젝트 |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) 이동됨', 'Game Object |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) déplacé.', 'Spielobjekt |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) verschoben', '游戏对象 |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) 已移动', NULL, 'Objeto de juego |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) movido', NULL, 'Игровой объект |cffffffff|Hgameobject:%d|h[%s]|h|r (GUID: %u) перемещен'),
(278, 'You must select a vendor', '공급업체를 선택해야 합니다.', 'Vous devez sélectionner un vendeur', 'Sie müssen einen Anbieter auswählen', '您必须选择供应商', NULL, 'Debe seleccionar un proveedor', NULL, 'Вы должны выбрать поставщика'),
(279, 'You must send id for item', '항목에 대한 ID를 보내야 합니다.', 'Vous devez indiquer un ID pour l''équipement', 'Sie müssen eine ID für den Artikel senden', '您必须为项目发送 id', NULL, 'Debe enviar identificación para el artículo', NULL, 'Вы должны отправить идентификатор товара'),
(280, 'Vendor has too many items (max 128)', '공급업체에 너무 많은 항목이 있습니다(최대 128개).', 'Le vendeur possède trop d''équipements (max 128).', 'Lieferant hat zu viele Artikel (max. 128)', '供应商的商品过多（最多 128 个）', NULL, 'El proveedor tiene demasiados artículos (máximo 128)', NULL, 'У продавца слишком много предметов (максимум 128)'),
(281, 'You can''t kick self, logout instead', '스스로를 버릴 수 없습니다. 대신 로그아웃하세요.', 'Vous ne pouvez pas vous kicker vous-même, déconnectez-vous plutôt.', 'Du kannst dich nicht selbst kicken, logge dich stattdessen aus', '你不能踢自己，而是注销', NULL, 'No puedes patearte a ti mismo, cierra la sesión en su lugar', NULL, 'Вы не можете кикать себя, вместо этого выйдите из системы'),
(282, 'Player %s kicked.', '플레이어 %s이(가) 찼습니다.', 'Joueur %s kické.', 'Spieler %s gekickt.', '球员 %s 踢了。', NULL, 'Jugador %s expulsado.', NULL, 'Игрок %s исключен.'),
(284, 'Accepting Whisper: %s', '귓속말 수락: %s', 'Acceptation des chuchotements: %s', 'Akzeptiere Flüstern: %s', '接受耳语：%s', NULL, 'Aceptando Susurro: %s', NULL, 'Принятие шепота: %s'),
(285, 'Accepting Whisper: ON', '귓속말 수락: ON', 'Acceptation des chuchotements: ON', 'Flüstern akzeptieren: EIN', '接受耳语：开', NULL, 'Aceptar susurro: ON', NULL, 'Прием шепота: ВКЛ.'),
(286, 'Accepting Whisper: OFF', '귓속말 수락: OFF', 'Acceptation des chuchotements: OFF', 'Flüstern akzeptieren: AUS', '接受耳语：关闭', NULL, 'Aceptar susurro: APAGADO', NULL, 'Прием шепота: ВЫКЛ.'),
(287, 'Creature (GUID: %u) not found', '생물(GUID: %u)을 찾을 수 없습니다.', 'Créature (GUID: %u) introuvable', 'Kreatur (GUID: %u) nicht gefunden', '未找到生物（GUID：%u）', NULL, 'Criatura (GUID: %u) no encontrada', NULL, 'Существо (GUID: %u) не найдено'),
(288, 'Tickets count: %i show new tickets: %s
