(380, '%d%s - |cffffffff|Hcreature:%d|h[%s X:%f Y:%f Z:%f MapId:%d]|h|r Chance:%f %s', '%d%s - |cffffffff|H생물:%d|h[%s X:%f Y:%f Z:%f 지도 ID:%d]|h|r 확률:%f %s', '%d%s - |cffffffff|Hcréature :%d|h[%s X :%f Y :%f Z :%f MapId :%d]|h|r Chance :%f %s', '%d%s - |cffffffff|HKreatur:%d|h[%s X:%f Y:%f Z:%f MapId:%d]|h|r Chance:%f %s', NULL, NULL, '%d%s - |cffffffff|Hcriatura:%d|h[%s X:%f Y:%f Z:%f MapId:%d]|h|r Oportunidad:%f %s', NULL, '%d%s - |cffffffff|Hcreature:%d|h[%s X:%f Y:%f Z:%f MapId:%d]|h|r Шанс:%f %s'),
(381, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d Chance:%f %s', '%d%s - [%s] X:%f Y:%f Z:%f 맵 ID:%d 기회:%f %s', '%d%s - [%s] X :%f Y :%f Z :%f MapId :%d Chance :%f %s', NULL, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d 机会:%f %s', NULL, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d Oportunidad:%f %s', NULL, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d Шанс:%f %s'),
(382, '%d%s - |cffffffff|Hcreature:%d|h[%s X:%f Y:%f Z:%f MapId:%d]|h|r %s', '%d%s - |cffffffff|H생물:%d|h[%s X:%f Y:%f Z:%f 지도 ID:%d]|h|r %s', '%d%s - |cffffffff|Hcréature :%d|h[%s X :%f Y :%f Z :%f MapId :%d]|h|r %s', '%d%s - |cffffffff|Hkreatur:%d|h[%s X:%f Y:%f Z:%f MapId:%d]|h|r %s', NULL, NULL, '%d%s - |cffffffff|Hcriatura:%d|h[%s X:%f Y:%f Z:%f MapId:%d]|h|r %s', NULL, NULL),
(383, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d %s', '%d%s - [%s] X:%f Y:%f Z:%f 맵 ID:%d %s', '%d%s - [%s] X :%f Y :%f Z :%f MapId :%d %s', NULL, NULL, NULL, NULL, NULL, NULL),
