(385, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d Chance:%f %s', '%d%s - [%s] X:%f Y:%f Z:%f 맵 ID:%d 기회:%f %s', '%d%s - [%s] X :%f Y :%f Z :%f MapId :%d Chance :%f %s', NULL, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d 机会:%f %s', NULL, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d Oportunidad:%f %s', NULL, '%d%s - [%s] X:%f Y:%f Z:%f MapId:%d Шанс:%f %s'),
