(400, '|cffff0000[System Message]:|rScripts reloaded', '|cffff0000[시스템 메시지]:|rScripts reloaded', '|cffff0000[Message Système]:|r Scripts rechargés', '|cffff0000[Systemmeldung]:|rScripts neu geladen', '|cffff0000[系统消息]：|rScripts 已重新加载', NULL, '|cffff0000[Mensaje del sistema]:|rScripts recargados', NULL, '|cffff0000[Системное сообщение]:|rScripts перезагружены'),
(401, 'You change security level of account %s to %i.', '계정 %s의 보안 수준을 %i로 변경합니다.', 'Vous modifiez le niveau de sécurité du compte %s à %i.', 'Sie ändern die Sicherheitsstufe von Konto %s auf %i.', '您将帐户 %s 的安全级别更改为 %i。', NULL, 'Cambia el nivel de seguridad de la cuenta %s a %i.', NULL, 'Вы меняете уровень безопасности учетной записи %s на %i.'),
(402, '%s changed your security level to %i.', '%s가 보안 수준을 %i로 변경했습니다.', '%s a modifié votre niveau de sécurité à %i.', '%s hat Ihre Sicherheitsstufe auf %i geändert.', '%s 将您的安全级别更改为 %i。', NULL, '%s cambió su nivel de seguridad a %i.', NULL, '%s изменил ваш уровень безопасности на %i.'),
(403, 'You have low security level for this.', '이에 대한 보안 수준이 낮습니다.', 'Vous avez un niveau de sécurité trop bas pour cela.', 'Sie haben dafür eine niedrige Sicherheitsstufe.', '您对此的安全级别较低。', NULL, 'Tienes un bajo nivel de seguridad para esto.', NULL, 'У вас низкий уровень безопасности для этого.'),
(404, 'Creature movement disabled.', '생물 이동이 비활성화되었습니다.', 'Mouvements de la créature désactivés.', 'Kreaturenbewegung deaktiviert.', '禁用生物移动。', NULL, 'Movimiento de criatura deshabilitado.', NULL, 'Движение существ отключено.'),
(405, 'Creature movement enabled.', '생물 이동이 활성화되었습니다.', 'Mouvements de la créature activés.', 'Kreaturenbewegung aktiviert.', '启用生物移动。', NULL, 'Movimiento de criatura habilitado.', NULL, 'Движение существ включено.'),
(406, 'Weather can''t be changed for this zone.', '이 지역의 날씨는 변경할 수 없습니다.', 'La météorologie ne peut pas être changée dans cette zone.', 'Das Wetter kann für diese Zone nicht geändert werden.', '无法更改此区域的天气。', NULL, 'El tiempo no se puede cambiar para esta zona.', NULL, 'Погода не может быть изменена для этой зоны.'),
