(410, '%s %s not found', '%s %s 찾을 수 없음', '%s %s introuvable.', '%s %s nicht gefunden', '%s %s 未找到', NULL, '%s %s no encontrado', NULL, '%s %s не найдено'),
(411, '%s unbanned. Notes: %s', NULL, NULL, NULL, NULL, NULL, NULL, NULL, NULL),
