INSERT INTO "world"."mangos_string" ("entry", "content_default", "content_loc1", "content_loc2", "content_loc3", "content_loc4", "content_loc5", "content_loc6", "content_loc7", "content_loc8") VALUES
(482, 'Character dump failed!', '캐릭터 덤프 실패!', 'Echec lors de l''exportation du personnage !', 'Zeichenabzug fehlgeschlagen!', '字符转储失败！', NULL, '¡El volcado de caracteres falló!', NULL, 'Не удалось создать дамп персонажа!'),
(483, 'Spell %u broken and not allowed to cast or learn!', '철자 %u가 깨져서 캐스팅하거나 배울 수 없습니다!', 'Sort %u défaillant et impossible à incanter ou apprendre !', 'Zauber %u gebrochen und darf nicht gewirkt oder gelernt werden!', '法术 %u 损坏，不允许施放或学习！', NULL, '¡Se rompe el hechizo %u y no se permite lanzarlo ni aprenderlo!', NULL, 'Заклинание %u сломано и не может быть разыграно или изучено!'),
(484, 'Skill %u (%s) for player %s set to %u and current maximum set to %u (without permanent (talent) bonuses).', NULL, 'La compétence %u (%s) pour le joueur %s a été mise à %u avec un maximum de %u (sans bonus (talents) permanent).', 'Skill %u (%s) für Spieler %s auf %u gesetzt und aktuelles Maximum auf %u gesetzt (ohne permanente (Talent-) Boni).', NULL, NULL, 'Habilidad %u (%s) para el jugador %s establecido en %u y máximo actual establecido en %u (sin bonificaciones permanentes (talentos)).', NULL, 'Навык %u (%s) для игрока %s установлен на %u, а текущий максимум установлен на %u (без постоянных (талант) бонусов).'),
(485, 'Player %s must have skill %u (%s) before using this command.', '플레이어 %s는 이 명령을 사용하기 전에 %u(%s) 스킬을 가지고 있어야 합니다.', 'Le joueur %s doit posséder la compétence %u (%s) avant d''utiliser cette commande.', 'Spieler %s muss die Fertigkeit %u (%s) haben, bevor er diesen Befehl verwendet.', '玩家 %s 必须具备技能 %u (%s) 才能使用此命令。', NULL, 'El jugador %s debe tener la habilidad %u (%s) antes de usar este comando.', NULL, 'Игрок %s должен иметь навык %u (%s) перед использованием этой команды.'),
(486, 'Invalid skill id (%u)', '잘못된 기술 ID(%u)', 'ID de compétence invalide (%u)', 'Ungültige Skill-ID (%u)', '技能 ID 无效 (%u)', NULL, 'Identificación de habilidad no válida (%u)', NULL, 'Недопустимый идентификатор навыка (%u)'),
(487, 'You learned default GM spells/skills.', '기본 GM 주문/기술을 배웠습니다.', 'Vous avez appris les sorts/compétences de base du MJ.', 'Du hast Standard-GM-Zauber/Fähigkeiten erlernt.', '你学会了默认的 GM 法术/技能。', NULL, 'Has aprendido hechizos/habilidades predeterminados de GM.', NULL, 'Вы изучили стандартные заклинания/навыки GM.'),
(488, 'You already know that spell.', '당신은 이미 그 주문을 알고 있습니다.', 'Vous connaissez déjà ce sort.', 'Du kennst diesen Zauber bereits.', '你已经知道那个咒语了。', NULL, 'Ya conoces ese hechizo.', NULL, 'Ты уже знаешь это заклинание.'),
(489, 'Target(%s) already know that spell.', '대상(%s)은 이미 그 주문을 알고 있습니다.', 'La cible (%s) connait déjà ce sort.', 'Ziel(%s) kennt diesen Zauber bereits.', '目标（%s）已经知道那个咒语。', NULL, 'El objetivo (%s) ya conoce ese hechizo.', NULL, 'Цель(%s) уже знает это заклинание.'),
(490, '%s doesn''t know that spell.', '%s는 그 주문을 모릅니다.', '%s ne connait pas ce sort.', '%s kennt diesen Zauber nicht.', '%s 不知道那个咒语。', NULL, '%s no conoce ese hechizo.', NULL, '%s не знает этого заклинания.'),
(491, 'You already forgot that spell.', '당신은 이미 그 주문을 잊었습니다.', 'Vous avez déjà oublié ce sort.', 'Du hast diesen Zauber bereits vergessen.', '你已经忘记了那个咒语。', NULL, 'Ya olvidaste ese hechizo.', NULL, 'Ты уже забыл это заклинание.'),
(492, 'All spell cooldowns removed for %s.', '%s에 대한 모든 주문 쿨다운이 제거되었습니다.', 'Tous les temps de rechargement des sorts ont été supprimés pour %s.', 'Alle Zauber-Cooldowns für %s entfernt.', '移除了 %s 的所有法术冷却时间。', NULL, 'Se eliminaron todos los tiempos de reutilización de hechizos para %s.', NULL, 'Все перезарядки заклинаний удалены на %s.'),
(493, 'Spell %u cooldown removed for %s.', NULL, 'Le temps de rechargement du sort %u a été supprimé pour %s.', 'Abklingzeit von Zauber %u für %s entfernt.', NULL, NULL, 'Se eliminó el tiempo de reutilización del hechizo %u para %s.', NULL, 'Перезарядка заклинания %u удалена на %s.'),
(494, 'Command : Additem, itemId = %i, amount = %i', '명령 : 항목 추가, 항목 ID = %i, 금액 = %i', 'Commande: Additem, ID de l''équipement = %i, quantité = %i', 'Befehl: Artikel hinzufügen, Artikel-ID = %i, Betrag = %i', '命令：Additem，itemId = %i，数量 = %i', NULL, 'Comando: Additem, itemId = %i, cantidad = %i', NULL, 'Команда: добавить элемент, itemId = %i, количество = %i'),
(495, 'Command : Additemset, itemsetId = %i', '명령 : 항목 집합 추가, 항목 집합 ID = %i', 'Commande: Additemset, ID du SET = %i', 'Befehl: Additemset, itemsetId = %i', '命令：Additemset，itemsetId = %i', NULL, 'Comando: Additemset, itemsetId = %i', NULL, 'Команда: Additemset, itemsetId = %i'),
(496, 'Removed itemID = %i, amount = %i from %s', '제거된 itemID = %i, amount = %i에서 %s', 'Suppression de l''équipement d''ID = %i, Quantité = %i de %s', 'ItemID = %i, Betrag = %i aus %s entfernt', NULL, NULL, 'ItemID eliminado = %i, cantidad = %i de %s', NULL, 'Удален itemID = %i, сумма = %i из %s'),
(497, 'Cannot create item ''%i'' (amount: %i)', '항목 ''%i''을(를) 만들 수 없습니다(금액: %i).', 'Impossible de créer l''équipement ''%i'' (quantité: %i)', 'Artikel ''%i'' kann nicht erstellt werden (Menge: %i)', '无法创建项目“%i”（数量：%i）', NULL, 'No se puede crear el artículo ''%i'' (cantidad: %i)', NULL, NULL),
(498, 'You need to provide a guild name!', '길드 이름을 입력해야 합니다!', 'Vous devez spécifier un nom de guilde !', 'Sie müssen einen Gildennamen angeben!', '您需要提供公会名称！', NULL, '¡Necesitas proporcionar un nombre de gremio!', NULL, 'Вам необходимо указать название гильдии!'),
(499, 'Player not found!', '플레이어를 찾을 수 없습니다!', 'Joueur introuvable !', 'Spieler nicht gefunden!', '找不到播放器！', NULL, '¡Jugador no encontrado!', NULL, 'Игрок не найден!'),
(500, 'Player already has a guild!', '플레이어는 이미 길드가 있습니다!', 'Le joueur possède déjà une guilde !', 'Spieler hat bereits eine Gilde!', '玩家已经有一个公会！', NULL, '¡El jugador ya tiene un gremio!', NULL, 'У игрока уже есть гильдия!'),
