(2049, 'Ticket notifications enabled.', '티켓 알림이 활성화되었습니다.', 'Notifications de tickets activées.', 'Ticketbenachrichtigungen aktiviert.', '工单通知已启用。', NULL, 'Notificaciones de tickets habilitadas.', NULL, 'Уведомления о билетах включены.'),
(2050, 'Ticket notifications disabled.', '티켓 알림이 비활성화되었습니다.', 'Notifications de tickets désactivées.', 'Ticketbenachrichtigungen deaktiviert.', '工单通知已禁用。', NULL, 'Notificaciones de tickets deshabilitadas.', NULL, 'Уведомления о билетах отключены.'),
(351, 'You set wallclimb mode to %s for %s.', '%s에 대해 wallclimb 모드를 %s(으)로 설정했습니다.', 'Vous avez défini le mode wallclimb sur %s pour %s.', 'Sie haben den Wallclimb-Modus für %s auf %s gesetzt.', '您将 %s 的爬墙模式设置为 %s。', NULL, 'Configuraste el modo de escalar paredes en %s para %s.', NULL, 'Вы установили режим подъема по стене на %s для %s.'),
(900, 'You changed Strength of %s to %i.', '%s의 강도를 %i로 변경했습니다.', 'Vous avez changé la Force de %s en %i.', 'Du hast die Stärke von %s zu %i geändert.', '您将 %s 的强度更改为 %i。', NULL, 'Cambiaste la Fuerza de %s a %i.', NULL, 'Вы изменили Силу %s на %i.'),
(901, '%s changed your Strength to %i.', '%s이(가) 귀하의 힘을 %i로 변경했습니다.', '%s a changé votre Force en %i.', '%s hat deine Stärke zu %i geändert.', '%s 将你的强度更改为 %i。', NULL, '%s cambió tu Fuerza a %i.', NULL, '%s изменил вашу Силу на %i.'),
(902, 'You changed Agility of %s to %i.', '%s의 민첩성을 %i로 변경했습니다.', 'Vous avez changé l''agilité de %s en %i.', 'Du hast die Agilität von %s zu %i geändert.', '您将 %s 的 Agility 更改为 %i。', NULL, 'Cambiaste la Agilidad de %s a %i.', NULL, 'Вы изменили ловкость %s на %i.'),
