INSERT INTO "world"."npc_trainer_greeting" ("entry", "content_default", "content_loc1", "content_loc2", "content_loc3", "content_loc4", "content_loc5", "content_loc6", "content_loc7", "content_loc8") VALUES
(3601, 'Hello, hunter!  Ready for some training?', '', '', 'Hallo $GJäger:Jägerin;! Wollt Ihr ein bisschen üben?', '', '', '¡Hola, cazador!  ¿Listo para entrenar?', '', 'Привет, $gохотник:охотница;! Ну что, будешь учиться?'),
(3602, 'Hello, druid!  Ready for some training?', '', '', 'Hallo $GDruide:Druidin;! Wollt Ihr ein bisschen üben?', '', '', '¡Hola, druida!  ¿Listo para entrenar?', '', 'Приветствую тебя, друид! Тебе нужны новые знания?'),
(3603, 'With alchemy you can turn found herbs into healing and other types of potions.', '', '', 'Durch Alchemie verwandelt Ihr Käuter in Tränke.', '', '', 'A través de la alquimia, puedes crear pociones curativas y de otros tipos con las hierbas que encuentres.', 'A través de la alquimia, puedes crear pociones curativas y de otros tipos con las hierbas que encuentres.', 'Освоив алхимию, ты сможешь варить зелья из найденных растений.'),
(3604, 'Searching for herbs requires both knowledge and instinct.', '', '', 'Das Pflücken von Kräutern erfordert sowohl Wissen als auch Instinkt.', '', '', 'Para encontrar hierbas necesitas conocimientos e instinto.', 'Para encontrar hierbas necesitas conocimientos e instinto.', 'Чтобы разбираться в травах, нужны и знания, и чутье.'),
(3605, 'Greetings!  Can I teach you how to turn beast hides into armor?', '', '', 'Seid gegrüßt! Darf ich Euch lehren, wie man Tierhäute in Rüstungen verwandelt?', '', '', '¡Saludos!  ¿Puedo enseñarte a convertir pieles de bestia en armaduras?', '', 'Здравствуй! Хочешь научиться делать доспехи из шкур животных?'),
(3606, 'Enchanting is the art of improving existing items through magic. ', '', '', 'Verzaubern ist die Kunst, Gegenstände durch Magie zu verbessern.', '', '', 'Encantar es el arte de mejorar los objetos existentes con magia.', 'Encantar es el arte de mejorar los objetos existentes con magia.', 'Наложение чар - это искусство улучшения материальных объектов с помощью магии.'),
(3607, 'I can teach you how to use a fishing pole to catch fish.', '', '', 'Ich kann Euch zeigen, wie man mit einer Angelrute Fische fängt.', '', '', 'Puedo enseñarte a usar una caña de pescar para pescar.', '', 'Я могу научить тебя ловить рыбу.'),
