INSERT INTO "world"."npc_trainer_greeting" ("entry", "content_default", "content_loc1", "content_loc2", "content_loc3", "content_loc4", "content_loc5", "content_loc6", "content_loc7", "content_loc8") VALUES
(5147, 'Hello, paladin!  Ready for some training?', '', '', 'Hallo Paladin! Wollt Ihr ein bisschen üben?', '', '', '¡Hola, paladín!  ¿Listo para entrenar?', '', 'Привет тебе, паладин! Ты $gпришел:пришла; за знаниями?'),
(5148, 'Hello, paladin!  Ready for some training?', '', '', 'Hallo Paladin! Wollt Ihr ein bisschen üben?', '', '', '¡Hola, paladín!  ¿Listo para entrenar?', '', 'Привет тебе, паладин! Ты $gпришел:пришла; за знаниями?'),
