(153, 'You take all copper of %s.', '%s의 구리를 모두 가져갑니다.', 'Vous prenez tout l''argent de %s.', 'Du nimmst alles Kupfer von %s.', '你拿走了 %s 的所有铜币。', NULL, 'Tomas todo el cobre de %s.', NULL, 'Вы забираете всю медь %s.'),
(154, '%s took you all of your copper.', '%s는 당신의 구리를 모두 가져갔습니다.', '%s vous a pris tout votre argent.', '%s hat dir dein ganzes Kupfer genommen.', '%s 拿走了你所有的铜币。', NULL, '%s te quitó todo tu cobre.', NULL, '%s забрал у вас всю вашу медь.'),
