(156, '%s took %i copper from you.', '%s는 당신에게서 %i개의 구리를 가져갔습니다.', '%s vous a pris %i pièce(s) de cuivre.', '%s hat Ihnen %i Kupfer abgenommen.', '%s 拿走了你的 %i 个铜币。', NULL, '%s te quitó %i cobre.', NULL, '%s забрал у вас %i меди.'),
(157, 'You give %i copper to %s.', '당신은 %i 구리를 %s에게 줍니다.', 'Vous donnez %i pièce(s) de cuivre à %s.', NULL, '你给 %i 铜币给 %s。', NULL, 'Le das %i cobre a %s.', NULL, 'Вы отдаете %i меди %s.'),
(158, '%s gave you %i copper.', '%s는 당신에게 %i개의 구리를 주었습니다.', '%s vous a donné %i pièce(s) de cuivre.', '%s hat dir %i Kupfer gegeben.', '%s 给了你 %i 铜币。', NULL, '%s te dio %i cobre.', NULL, '%s дал вам %i меди.'),
