(337, 'All your items repaired by %s.', '%s에 의해 모든 항목이 수리되었습니다.', 'Tous vos équipements ont été réparés par %s.', 'Alle Ihre Artikel wurden von %s repariert.', '%s 修理了你所有的物品。', NULL, 'Todos tus artículos reparados por %s.', NULL, 'Все ваши предметы отремонтированы %s.'),
(338, 'You set waterwalk mode to %s for %s.', '%s에 대해 워터워크 모드를 %s(으)로 설정했습니다.', 'Vous configurez le mode Marche-sur-eau à %s pour %s.', 'Sie haben den Wasserlaufmodus für %s auf %s gesetzt.', '您将 %s 的水上行走模式设置为 %s。', NULL, 'Configuraste el modo Waterwalk en %s para %s.', NULL, 'Вы установили режим хождения по воде на %s для %s.'),
(339, 'Your waterwalk mode has been turned %s by %s.', '워터워크 모드가 %s에 의해 %s로 변경되었습니다.', 'Votre mode Marche-sur-eau a été configuré à %s par %s.', 'Ihr Wasserlaufmodus wurde von %s auf %s geändert.', '您的水上行走模式已被 %s 转换为 %s。', NULL, 'Su modo Waterwalk ha sido activado %s por %s.', NULL, 'Ваш режим хождения по воде был изменен на %s пользователем %s.'),
(340, '%s is now following you.', '%s이(가) 당신을 팔로우하고 있습니다.', '%s est en train de vous suivre.', '%s folgt Ihnen jetzt.', '%s 现在正在关注你。', NULL, '%s ahora te está siguiendo.', NULL, '%s теперь следует за вами.'),
(341, '%s is not following you.', '%s님은 당신을 팔로우하고 있지 않습니다.', '%s ne vous suit plus.', '%s folgt Ihnen nicht.', '%s 没有关注你。', NULL, '%s no te está siguiendo.', NULL, '%s не следит за вами.'),
(342, '%s is now not following you.', '%s은(는) 현재 귀하를 팔로우하고 있지 않습니다.', '%s n''est plus en train de vous suivre.', '%s folgt Ihnen jetzt nicht.', '%s 现在没有关注你。', NULL, '%s ya no te sigue.', NULL, '%s больше не подписан на вас.'),
(343, 'Creature (Entry: %u) cannot be tamed.', '생물(항목: %u)은 길들일 수 없습니다.', 'La créature (Entry: %u) ne peut pas être domptée.', 'Kreatur (Eintrag: %u) kann nicht gezähmt werden.', '无法驯服生物（条目：%u）。', NULL, 'La criatura (Entrada: %u) no puede ser domesticada.', NULL, 'Существо (Запись: %u) нельзя приручить.'),
(344, 'You already have pet.', '당신은 이미 애완 동물이 있습니다.', 'Vous possédez déjà un familier.', 'Sie haben bereits ein Haustier.', '你已经有宠物了。', NULL, 'Ya tienes mascota.', NULL, 'У вас уже есть питомец.'),
