(659, '$n has assaulted the %s', '$n이 %s를 공격했습니다.', '$N a attaqué %s.', '$n hat %s angegriffen', '$n 袭击了 %s', NULL, '$n ha atacado a %s', NULL, '$n напал на %s'),
(660, '$n claims the %s! If left unchallenged, the %s will control it in 1 minute!', NULL, '$N a pris %s ! Si personne n''intervient, %s s''en emparera dans 1 minute !', NULL, NULL, NULL, NULL, NULL, NULL),
(50, 'This command is not available to you.', '이 명령은 사용할 수 없습니다.', 'Cette commande n''est pas disponible pour vous.', 'Dieser Befehl steht Ihnen nicht zur Verfügung.', '您无法使用此命令。', '您無法使用此命令。', 'Este comando no está disponible para usted.', 'Este comando no está disponible para usted.', 'Эта команда вам недоступна.'),
(181, '[PlayerBotMgr] |cffe1101cAdding level %u horde battlebot to bg queue %u.|r', '[PlayerBotMgr] |cffe1101c레벨 %u 호드 배틀봇을 bg 대기열 %u에 추가합니다.|r', '[PlayerBotMgr] |cffe1101cAjout de la Horde Battlebot de niveau %u à la file d''attente BG %u.|r', '[PlayerBotMgr] |cffe1101cFüge einen Level %u Horde-Battlebot zur Warteschlange %u hinzu.|r', '[PlayerBotMgr] |cffe1101c将 %u 级部落Battlebot添加到BG队列 %u。|r', '[PlayerBotMgr] |cffe1101c將 %u 級部落Battlebot添加到BG隊列 %u。|r', '[PlayerBotMgr] |cffe1101cAgregar nivel %u Horde Battlebot a BG Queue %u.|r', NULL, '[PlayerBotMgr] |cffe1101cДобавление уровня %u Horde Battlebot в очередь BG %u.|r'),
(666, 'After your recent battle in %s our best attempts to award you a Mark of Honor failed. Enclosed you will find the Mark of Honor we were not able to deliver to you at the time. Thanks for fighting in %s!', NULL, 'Suite à votre récente bataille dans %s, nous avons tenté de vous récompenser avec une marque d’honneur, mais sans succès. Vous trouverez ci-joint la marque d’honneur que nous n’avons pas pu vous remettre sur le moment. Merci d’avoir combattu dans %s !', NULL, NULL, NULL, NULL, NULL, NULL),
(705, 'You must wait %s before speaking again.', '다시 말하기 전에 %s를 기다려야 합니다.', 'Vous devez attendre %s avant de retrouver la parole.', 'Sie müssen %s warten, bevor Sie erneut sprechen.', '您必须等待 %s 才能再次发言。', NULL, 'Debe esperar %s antes de volver a hablar.', NULL, 'Вы должны подождать %s, прежде чем говорить снова.'),
(706, 'This item(s) have problems with equipping/storing in inventory.', '이 아이템은 인벤토리에 장착/보관하는 데 문제가 있습니다.', 'Les équipements suivant ont des problèmes avec leur stockage dans l''inventaire.', 'Diese(r) Artikel hat/haben Probleme beim Ausrüsten/Lagern im Inventar.', '该物品在库存中的装备/存储方面存在问题。', NULL, 'Este(s) artículo(s) tiene(n) problemas con el equipamiento/almacenamiento en el inventario.', NULL, 'У этого предмета(ов) есть проблемы с экипировкой/хранением в инвентаре.'),
(707, '%s wishes to not be disturbed and cannot receive whisper messages: %s', '%s은(는) 방해받지 않기를 원하며 귓속말 메시지를 받을 수 없습니다: %s', '%s ne souhaite pas être dérangé et ne peut pas recevoir de chuchotements: %s', '%s möchte nicht gestört werden und kann keine Flüsternachrichten empfangen: %s', '%s 希望不被打扰并且不能接收耳语消息：%s', NULL, '%s desea que no lo molesten y no puede recibir mensajes susurrados: %s', NULL, '%s не хочет, чтобы его беспокоили, и не может получать сообщения шепотом: %s'),
(708, '%s is Away from Keyboard: %s', '%s는 키보드에서 자리를 비웠습니다: %s', '%s est absent: %s', '%s ist nicht in der Tastatur: %s', '%s 离开键盘：%s', NULL, '%s está lejos del teclado: %s', NULL, '%s находится далеко от клавиатуры: %s'),
(709, 'Do not Disturb', '방해하지 마', 'Ne pas déranger', 'Bitte nicht stören', '请勿打扰', NULL, 'No molestar', NULL, 'Просьба не беспокоить'),
(710, 'Away from Keyboard', '키보드에서 떨어져', 'Absent', 'Nicht am Computer', '远离键盘', NULL, 'Lejos del teclado', NULL, 'Вдали от клавиатуры'),
(711, 'Queue status for %s (Lvl: %u to %u)
